        address taxVault_,
        uint256 buyTax_,
        uint256 sellTax_,
        uint256 antiSniperBuyTaxStartValue_,
        address antiSniperTaxVault_
    ) external initializer {
        __AccessControl_init();
        __ReentrancyGuard_init();
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);

        taxVault = taxVault_;
        buyTax = buyTax_;
        sellTax = sellTax_;
        antiSniperBuyTaxStartValue = antiSniperBuyTaxStartValue_;
        antiSniperTaxVault = antiSniperTaxVault_;
    }

    function _createPair(
        address tokenA,
        address tokenB,
        uint256 startTime,
        uint256 startTimeDelay
    ) internal returns (address) {
        require(tokenA != address(0), "Zero addresses are not allowed.");
        require(tokenB != address(0), "Zero addresses are not allowed.");
        require(router != address(0), "No router");

        FPairV2 pair_ = new FPairV2(
            router,
            tokenA,
            tokenB,
            startTime,
            startTimeDelay
        );

        _pair[tokenA][tokenB] = address(pair_);
        _pair[tokenB][tokenA] = address(pair_);

        pairs.push(address(pair_));

        emit PairCreated(tokenA, tokenB, address(pair_), pairs.length);

        return address(pair_);
    }

    function createPair(
        address tokenA,
        address tokenB,
        uint256 startTime,
        uint256 startTimeDelay
    ) external onlyRole(CREATOR_ROLE) nonReentrant returns (address) {
        return _createPair(tokenA, tokenB, startTime, startTimeDelay);
    }

    function getPair(
        address tokenA,
        address tokenB
    ) public view returns (address) {
        return _pair[tokenA][tokenB];
    }

    function allPairsLength() public view returns (uint) {
        return pairs.length;
    }

    function setTaxParams(
        address newVault_,
        uint256 buyTax_,
        uint256 sellTax_,
        uint256 antiSniperBuyTaxStartValue_,
        address antiSniperTaxVault_
    ) public onlyRole(ADMIN_ROLE) {
        require(newVault_ != address(0), "Zero addresses are not allowed.");
        require(antiSniperTaxVault_ != address(0), "Zero address not allowed for antiSniperTaxVault");
        require(buyTax_ <= 99, "buyTax exceeds maximum");
        require(sellTax_ <= 99, "sellTax exceeds maximum");
        require(antiSniperBuyTaxStartValue_ <= 99, "antiSniper exceeds maximum");
        require(buyTax_ + antiSniperBuyTaxStartValue_ <= 100, "Tax sum exceeds 100%");

        taxVault = newVault_;
        buyTax = buyTax_;
        sellTax = sellTax_;
        antiSniperBuyTaxStartValue = antiSniperBuyTaxStartValue_;
        antiSniperTaxVault = antiSniperTaxVault_;
    }

    function setRouter(address router_) public onlyRole(ADMIN_ROLE) {
        router = router_;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

import "./IFPairV2.sol";

contract FPairV2 is IFPairV2, ReentrancyGuard {
    using SafeERC20 for IERC20;

    address public router;
    address public tokenA; // agent token
    address public tokenB; // asset token

    struct Pool {
        uint256 reserve0;
        uint256 reserve1;
        uint256 k;
        uint256 lastUpdated;
    }

    Pool private _pool;
    uint256 public startTime;
    uint256 public startTimeDelay;
    uint256 public taxStartTime; // Time when anti-sniper tax starts counting down

    constructor(
        address router_,
        address token0,
        address token1,
        uint256 startTime_,
        uint256 startTimeDelay_
    ) {
        require(router_ != address(0), "Zero addresses are not allowed.");
        require(token0 != address(0), "Zero addresses are not allowed.");
        require(token1 != address(0), "Zero addresses are not allowed.");

        router = router_;
        tokenA = token0;
        tokenB = token1;
        startTime = startTime_;
        startTimeDelay = startTimeDelay_;
        taxStartTime = 0; // Initialize to 0, will be set when launched
    }

    event Mint(uint256 reserve0, uint256 reserve1);

    event Swap(
        uint256 amount0In,
        uint256 amount0Out,
        uint256 amount1In,
        uint256 amount1Out
    );

    event TimeReset(uint256 oldStartTime, uint256 newStartTime);
    event TaxStartTimeSet(uint256 taxStartTime);
    event Sync(uint256 reserve0, uint256 reserve1);

    modifier onlyRouter() {
        require(router == msg.sender, "Only router can call this function");
        _;
    }

    error InvalidStartTime();

    function mint(
        uint256 reserve0,
        uint256 reserve1
    ) public onlyRouter returns (bool) {
        require(_pool.lastUpdated == 0, "Already minted");

        _pool = Pool({
            reserve0: reserve0,
            reserve1: reserve1,
            k: reserve0 * reserve1,
            lastUpdated: block.timestamp
        });

        emit Mint(reserve0, reserve1);

        return true;
    }

    function swap(
        uint256 amount0In,
        uint256 amount0Out,
        uint256 amount1In,
        uint256 amount1Out
    ) public onlyRouter returns (bool) {
        require(block.timestamp >= startTime, "Swap not started");

        uint256 _reserve0 = (_pool.reserve0 + amount0In) - amount0Out;
        uint256 _reserve1 = (_pool.reserve1 + amount1In) - amount1Out;

        _pool = Pool({
            reserve0: _reserve0,
            reserve1: _reserve1,
            k: _pool.k,
            lastUpdated: block.timestamp
        });

        emit Swap(amount0In, amount0Out, amount1In, amount1Out);

        return true;
    }

    function approval(
        address _user,
        address _token,
        uint256 amount
    ) public onlyRouter returns (bool) {
        require(_user != address(0), "Zero addresses are not allowed.");
        require(_token != address(0), "Zero addresses are not allowed.");

        IERC20 token = IERC20(_token);

        token.forceApprove(_user, amount);

        return true;
    }

    function transferAsset(
        address recipient,
        uint256 amount
    ) public onlyRouter {
        require(recipient != address(0), "Zero addresses are not allowed.");

        IERC20(tokenB).safeTransfer(recipient, amount);
    }

    function transferTo(address recipient, uint256 amount) public onlyRouter {
        require(recipient != address(0), "Zero addresses are not allowed.");

        IERC20(tokenA).safeTransfer(recipient, amount);
    }

    /**
     * @dev Sync reserves after drain operations to maintain state consistency
     * Should be called after drainPrivatePool to update reserves
     * @param assetAmount Amount of asset tokens (tokenB) transferred out
     * @param tokenAmount Amount of agent tokens (tokenA) transferred out
     */
    function syncAfterDrain(
        uint256 assetAmount,
        uint256 tokenAmount
    ) public onlyRouter {
        // Subtract transferred amounts (don't use balanceOf due to virtual liquidity)
        _pool.reserve0 = _pool.reserve0 >= tokenAmount
            ? _pool.reserve0 - tokenAmount
            : 0;
        _pool.reserve1 = _pool.reserve1 >= assetAmount
            ? _pool.reserve1 - assetAmount
            : 0;
        _pool.k = _pool.reserve0 * _pool.reserve1;
        emit Sync(_pool.reserve0, _pool.reserve1);
    }

    function getReserves() public view returns (uint256, uint256) {
        return (_pool.reserve0, _pool.reserve1);
    }

    function kLast() public view returns (uint256) {
        return _pool.k;
    }

    function priceALast() public view returns (uint256) {
        return _pool.reserve1 / _pool.reserve0;
    }

    function priceBLast() public view returns (uint256) {
        return _pool.reserve0 / _pool.reserve1;
    }

    function balance() public view returns (uint256) {
        return IERC20(tokenA).balanceOf(address(this));
    }

    function assetBalance() public view returns (uint256) {
        return IERC20(tokenB).balanceOf(address(this));
    }

    function resetTime(uint256 newStartTime) public onlyRouter nonReentrant {
        if (block.timestamp >= startTime) {
            revert InvalidStartTime();
        }
        // Ensure newStartTime meets the minimum delay requirement
        if (newStartTime < block.timestamp + startTimeDelay) {
            revert InvalidStartTime();
        }

        uint256 oldStartTime = startTime;
        startTime = newStartTime;
        emit TimeReset(oldStartTime, newStartTime);
    }

    function setTaxStartTime(uint256 _taxStartTime) public onlyRouter {
        // BE will input the _taxStartTime = time when call Launch(), so it's always after or at least equal to the startTime
        require(
            _taxStartTime >= startTime,
            "Tax start time must be greater than startTime"
        );
        taxStartTime = _taxStartTime;
        emit TaxStartTimeSet(_taxStartTime);
    }
}

